#!/usr/bin/env bash
# Сверка выдачи регресса с картиной известных провалов (DBU-15).
#
# Набор намеренно не гейт: красный кейс на версии-кандидате не должен ронять
# нашу работу. Но из-за этого «success» означал лишь «прогон дошёл до конца», а
# вердикты жили ТОЛЬКО в логе — и потеря лога делала прогон неотличимым от
# непроведённого (замерено 30.08.2026 на задании 14626).
#
# Здесь сравнивается не «есть ли провалы», а СОВПАДАЕТ ЛИ КАРТИНА с
# db-regression-known.tsv. Тогда сам ЗНАЧОК задания несёт смысл и переживает
# потерю лога: зелёный — «ничего не изменилось», красный — «изменилось».
#
# Обе стороны отклонения — новость:
#   · новый провал = регресс;
#   · известный провал ПРОШЁЛ = чужая починка доехала, обходной путь пора
#     снимать. Молчать об этом значит носить костыль после того, как он стал
#     не нужен.
#
# Вход: <версия> <файл-выдачи>. Код возврата 1 при любом расхождении.
set -uo pipefail

VER="${1:?версия обязательна}"
FILE="${2:?файл выдачи обязателен}"
KNOWN="$(dirname "$0")/db-regression-known.tsv"

if [ ! -s "$FILE" ]; then
  echo "::error::выдачи для $VER нет — сверять нечего, прогон не состоялся"
  exit 1
fi
if [ ! -s "$KNOWN" ]; then
  echo "::error::нет файла известных провалов ($KNOWN) — сверка невозможна"
  exit 1
fi

# Ожидаемые провалы этой версии.
expected=$(grep -v '^#' "$KNOWN" | awk -F'\t' -v v="$VER" 'NF>=2 && $1==v {print $2}' | sort -u)
# Фактические провалы.
actual=$(grep -P '\tFAIL\t' "$FILE" | cut -f1 | sort -u)

new_fails=$(comm -13 <(printf '%s\n' "$expected") <(printf '%s\n' "$actual"))
now_pass=$(comm -23 <(printf '%s\n' "$expected") <(printf '%s\n' "$actual"))

rc=0
if [ -n "$new_fails" ]; then
  echo "::error::$VER — НОВЫЕ провалы, которых нет в известных:"
  printf '%s\n' "$new_fails" | while IFS= read -r c; do
    [ -n "$c" ] && echo "::error::  $c — $(grep -P "^$c\t" "$FILE" | cut -f3 | head -c 200)"
  done
  rc=1
fi
if [ -n "$now_pass" ]; then
  echo "::error::$VER — известные провалы БОЛЬШЕ НЕ ВОСПРОИЗВОДЯТСЯ (починка доехала, обходной путь пора снимать):"
  printf '%s\n' "$now_pass" | while IFS= read -r c; do
    [ -n "$c" ] && echo "::error::  $c"
  done
  rc=1
fi
[ "$rc" -eq 0 ] && echo "$VER: картина совпадает с известной (ожидаемых провалов: $(printf '%s\n' "$expected" | grep -c .))"
exit "$rc"
